int arr[] = {10, 20, 30, 40, 50};
// arr 的值 == &arr[0] (第一个元素的地址)
int *p = arr; // 数组名直接赋值给指针变量
cout << *p << endl; // 输出 10，访问第一个元素
cout << *(p+2) << endl; // 输出 30，访问第三个元素

int arr[] = {10, 20, 30, 40, 50};
int p = arr;// p 指向数组首元素 arr[0]
// 方式1：固定指针，偏移索引
for(inti = 0; i < 5; i++) {
cout << *(p + i) << endl;// 等价于 arr[i]
}
// 方式2：移动指针本身 (更高效)
for(p = arr; p < arr+5; p++) {
cout << *p << " ";// 直接取值，指针自增
}

