void swap(int a,intb) {// a,b 是外部变量的副本
inttemp = a; a = b; b = temp;// 仅修改副本
}

void swap(int *pa,int *pb) {// 接收变量地址
int t=*pa; *pa=*pb; *pb=t;// 直接修改原始数据
}

#include <cstdlib> // 引入头文件
int main() {
int n = 5; // 假设需要存储5个整数
// 分配内存：计算总字节数并强转
int *arr = (int*)malloc(n * sizeof(int));
if (arr == nullptr) { /* 处理分配失败 */ }
arr[0] = 10; // 正常使用内存
// ... 业务逻辑 ...
free(arr); // 必须释放！
arr = nullptr; // 避免悬空指针
return 0;
}

